package set_param

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "set_param"
	command.Identifiers = []string{"set-param"}
	command.Category = "Server System"
	command.Help = "Rewrite one declared query parameter of a route"
	command.LongDescription = "Rewrites one declared query parameter in place and runs build. It is add-param applied to a declaration that already exists: the keys given are written over the ones there, --clear takes one off, and the result goes through the same constructor — so adding a bound that was forgotten never means removing the parameter and declaring it again."
	command.Examples = []string{"set-param page --route list-users --type int --min 1 --max 50"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route (identifier or package name) the parameter is declared on",
			Examples:    []string{"set-param page --route list-users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--route"},
		},
		{
			Id:          "rename",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the query key it answers to from now on",
			Examples:    []string{"set-param page --route list-users --rename cursor"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--rename"},
		},
		{
			Id:          "type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the value type: string, boolean, int or float",
			Examples:    []string{"set-param page --route list-users --type int"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--type"},
		},
		{
			Id:          "description",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "help text shown for the parameter",
			Examples:    []string{"set-param page --route list-users --description 'the page to read'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--description"},
		},
		{
			Id:          "default",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the literal bound when the parameter is absent",
			Examples:    []string{"set-param page --route list-users --default 1"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--default"},
		},
		{
			Id:          "required",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "refuse a request that does not carry the parameter",
			Examples:    []string{"set-param tenant --route list-users --required"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--required"},
		},
		{
			Id:          "array",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "collect every occurrence of the key into a []T field",
			Examples:    []string{"set-param tag --route list-users --array"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--array"},
		},
		{
			Id:          "min",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "smallest accepted value (int/float only)",
			Examples:    []string{"set-param page --route list-users --type int --min 1"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--min"},
		},
		{
			Id:          "max",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "largest accepted value (int/float only)",
			Examples:    []string{"set-param page --route list-users --type int --max 50"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--max"},
		},
		{
			Id:          "example",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a value the parameter takes, for the docs (repeatable; appended)",
			Examples:    []string{"set-param page --route list-users --example 2"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--example"},
		},
		{
			Id:          "clear",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a key to take off again: description, examples, default, required, array, min or max (repeatable)",
			Examples:    []string{"set-param page --route list-users --clear max"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--clear"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
		{
			Id:          "identifier",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "match only when the request brings exactly this value, putting the field into what the route matches on",
			Examples:    []string{"set-param mode --route debug --identifier verbose"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--identifier"},
		},
		{
			Id:          "starts-with",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "match only when the value the request brings begins with this, putting the field into what the route matches on",
			Examples:    []string{"set-param mode --route debug --starts-with verb"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--starts-with"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the query parameter to edit, by the key it is declared under",
			Examples:    []string{"set-param page --route list-users --max 50"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
